scripts:
Chart.defaults.font.family = "'Segoe UI','Helvetica Neue',Arial,sans-serif";
Chart.defaults.color = '#5b6472';

new Chart(document.getElementById('barChart'), {
  type: 'bar',
  data: {
    labels: ['Exigencia del mercado\n(WACC 9%)', 'CAGR real\nde FCF (5 años)', 'CAGR real\nde ingresos (5 años)', 'Consenso de analistas\n(crecimiento EPS FY27)'],
    datasets: [{
      data: [20.1, 1.9, 14.6, 14.0],
      backgroundColor: ['#c22','#1a56db','#5b8def','#0a7d3c'],
      borderRadius: 6
    }]
  },
  options: {
    plugins:{legend:{display:false}, title:{display:true, text:'Comparación de tasas de crecimiento anual promedio (%)', font:{size:12}}},
    scales:{y:{beginAtZero:true, ticks:{callback:v=>v+'%'}}}
  }
});
